const n0 = trigger({"type": "n8n-nodes-base.scheduleTrigger", "version": 1.3, "config": {"name": "A cada 5 minutos", "position": [0, 0], "parameters": {"rule": {"interval": [{"field": "minutes", "minutesInterval": 5}]}}}});
const n1 = node({"type": "n8n-nodes-base.postgres", "version": 2.6, "config": {"name": "Clientes esperando", "position": [224, 0], "credentials": {"postgres": {"id": "2QBGXkxxr41tWTQw", "name": "Postgres account"}}, "executeOnce": true, "alwaysOutputData": true, "parameters": {"operation": "executeQuery", "query": "CREATE TABLE IF NOT EXISTS gerente_cobranca (chave TEXT PRIMARY KEY, chat_id TEXT, grupo TEXT, desde TIMESTAMPTZ, n1_em TIMESTAMPTZ, n2_em TIMESTAMPTZ, n3_em TIMESTAMPTZ, respondido_em TIMESTAMPTZ, criado_em TIMESTAMPTZ DEFAULT now());\nALTER TABLE gerente_cobranca ADD COLUMN IF NOT EXISTS card_id TEXT, ADD COLUMN IF NOT EXISTS card_url TEXT, ADD COLUMN IF NOT EXISTS card_fechado TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS recebido_em TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS repetida_em TIMESTAMPTZ, ADD COLUMN IF NOT EXISTS alarme_em TIMESTAMPTZ;\n-- 17/11 (Henrique): não depende mais do Monitor. Resposta = mensagem humana da equipe (as automáticas de recebido/fora do expediente/almoço não contam). Janela de 5 dias (fim de semana).\nWITH team AS (\n  SELECT DISTINCT m.autor_jid FROM mensagens m\n  WHERE m.chat_id IN (SELECT chat_id FROM chats WHERE nome ILIKE '%pend%ncias%')\n    AND NOT m.from_me AND m.autor_jid IS NOT NULL\n  UNION SELECT '5581996928808@s.whatsapp.net'\n  UNION SELECT '5581995667045@s.whatsapp.net'\n),\ninternos AS (\n  SELECT DISTINCT chat_id FROM chats\n  WHERE nome ILIKE ANY (ARRAY['%pend%ncias%','%euforia | marketing%','%central de gest%','%sala de guerra%','%teste wo%','%aquecimento%'])\n  UNION SELECT '120363414189297847@g.us'\n),\nmsgs AS (\n  SELECT msg_id, min(chat_id) AS chat_id, min(enviado_em) AS enviado_em,\n         bool_or(from_me) OR bool_or(COALESCE(autor_nome,'') ILIKE '%euforia%') OR bool_or(autor_jid IN (SELECT autor_jid FROM team WHERE autor_jid IS NOT NULL)) AS da_equipe,\n         max(autor_nome) AS autor_nome, max(tipo) AS tipo, max(texto) AS texto\n  FROM mensagens\n  WHERE chat_id LIKE '%@g.us' AND enviado_em > now() - interval '5 days'\n  GROUP BY msg_id\n),\n-- 25/11 (caso Jean): só conta como resposta a mensagem que responde de verdade. Não contam: reação/figurinha, saudação ou 'ok' sozinhos,\n-- e retorno sem conteúdo ('vou verificar', 'irei conferir', 'te trago uma resposta hoje ainda'), que vira promessa de 24h no leitor de promessas.\nhumano AS (\n  SELECT * FROM msgs WHERE da_equipe\n    AND tipo NOT IN ('reactionMessage','stickerMessage','protocolMessage','pollUpdateMessage')\n    AND COALESCE(texto,'') !~* '^[[:space:][:punct:]]*(oi|ol[aá]|bom dia|boa tarde|boa noite|tudo bem|ok|okay|certo|claro|perfeito|beleza|combinado|show|entendi|obrigad[oa]s?)([[:space:][:punct:]]+[[:alpha:]]+)?[[:space:][:punct:]]*$'\n    AND NOT (COALESCE(texto,'') ~* '((vou|irei|vamos|iremos|estou|estamos|j[aá] estou|j[aá] estamos) (verificar|conferir|checar|averiguar|analisar|olhar|ver|vendo|verificando|conferindo|checando|olhando|analisando)|te (trago|dou|passo|retorno|respondo|aviso|falo)|j[aá] te (retorno|respondo|aviso|falo)|retorno (em breve|j[aá]|logo)|hoje ainda|ainda hoje|assim que (poss[ií]vel|tiver|eu tiver)|s[oó] um (momento|minutinho|minuto)|um instante)'\n             AND COALESCE(texto,'') !~* 'https?://')\n    AND COALESCE(texto,'') !~* '(sua mensagem chegou|recebemos sua mensagem|registramos sua mensagem|j[aá] vimos sua mensagem|time j[aá] est[aá] verificando|j[aá] estamos vendo isso|obrigada por escrever|fora do expediente|fora do hor[aá]rio de atendimento|hor[aá]rio de almo[cç]o|pausa para o almo[cç]o|intervalo de almo[cç]o|volta(mos)? do almo[cç]o|expediente)'\n),\npend AS (\n  SELECT ch.chat_id, (SELECT max(h.enviado_em) FROM humano h WHERE h.chat_id = ch.chat_id) AS ult_equipe\n  FROM (SELECT DISTINCT chat_id FROM msgs) ch\n  WHERE ch.chat_id NOT IN (SELECT chat_id FROM internos)\n    AND EXISTS (SELECT 1 FROM chats c WHERE c.chat_id = ch.chat_id AND c.origem LIKE 'suporte%')\n),\nupd AS (\n  UPDATE gerente_cobranca c SET respondido_em = (SELECT min(h.enviado_em) FROM humano h WHERE h.chat_id = c.chat_id AND h.enviado_em > c.desde)\n  WHERE c.respondido_em IS NULL AND EXISTS (SELECT 1 FROM humano h WHERE h.chat_id = c.chat_id AND h.enviado_em > c.desde)\n  RETURNING 1\n)\nSELECT p.chat_id || ':' || f.msg_id AS chave, p.chat_id,\n  COALESCE((SELECT c.nome FROM chats c WHERE c.chat_id = p.chat_id AND c.nome IS NOT NULL LIMIT 1), p.chat_id) AS grupo,\n  f.enviado_em AS desde, COALESCE(f.autor_nome, 'Cliente') AS autor, left(COALESCE(f.texto, '[' || f.tipo || ']'), 250) AS texto, a.todos, a.qtd,\n  (SELECT string_agg(to_char(x.enviado_em AT TIME ZONE 'America/Recife','DD/MM HH24:MI') || ' · ' || CASE WHEN x.da_equipe THEN 'EUFORIA' ELSE COALESCE(x.autor_nome,'Cliente') END || ': ' || left(COALESCE(x.texto, '[' || x.tipo || ']'), 500), E'\\n' ORDER BY x.enviado_em)\n     FROM (SELECT * FROM msgs y WHERE y.chat_id = p.chat_id AND y.tipo NOT IN ('reactionMessage','protocolMessage','pollUpdateMessage') ORDER BY y.enviado_em DESC LIMIT 15) x) AS conversa,\n  g.n1_em, g.n2_em, g.n3_em, g.recebido_em, g.card_id, g.card_url, g.repetida_em, g.alarme_em, a.ultima, (SELECT max(x.enviado_em) FROM msgs x WHERE x.chat_id = p.chat_id AND x.da_equipe AND x.tipo NOT IN ('reactionMessage','protocolMessage')) AS ult_qualquer, p.ult_equipe, (SELECT count(*) FROM upd) AS respondidos_agora\nFROM pend p\nCROSS JOIN LATERAL (SELECT * FROM msgs m WHERE m.chat_id = p.chat_id AND NOT m.da_equipe\n    AND m.tipo NOT IN ('reactionMessage','stickerMessage','protocolMessage','pollUpdateMessage')\n    AND m.enviado_em > COALESCE(p.ult_equipe, '-infinity'::timestamptz) ORDER BY m.enviado_em LIMIT 1) f\nCROSS JOIN LATERAL (SELECT count(*) AS qtd, max(m.enviado_em) AS ultima, string_agg(left(COALESCE(m.texto, '[' || m.tipo || ']'), 300), E'\\n' ORDER BY m.enviado_em) AS todos FROM msgs m WHERE m.chat_id = p.chat_id AND NOT m.da_equipe\n    AND m.tipo NOT IN ('reactionMessage','stickerMessage','protocolMessage','pollUpdateMessage')\n    AND m.enviado_em > COALESCE(p.ult_equipe, '-infinity'::timestamptz)) a\nLEFT JOIN gerente_cobranca g ON g.chave = p.chat_id || ':' || f.msg_id\nWHERE g.n3_em IS NULL OR g.card_id IS NULL\n   OR (g.repetida_em IS NULL AND a.qtd >= 2 AND a.ultima >= f.enviado_em + interval '30 minutes')\n   OR (g.alarme_em IS NULL AND a.todos ~* '(cancel|rescis|rescindir|distrato|falta de respeito|desrespeit|preju[ií]zo|procon|advogad|reclame ?aqui|processo judicial|a[cç][aã]o judicial)')\nORDER BY f.enviado_em LIMIT 60;\n", "options": {}}}});
const n2 = node({"type": "n8n-nodes-base.postgres", "version": 2.6, "config": {"name": "Cards respondidos", "position": [448, 0], "credentials": {"postgres": {"id": "2QBGXkxxr41tWTQw", "name": "Postgres account"}}, "executeOnce": true, "alwaysOutputData": true, "parameters": {"operation": "executeQuery", "query": "UPDATE gerente_cobranca SET card_fechado = now() WHERE respondido_em IS NOT NULL AND card_id IS NOT NULL AND card_fechado IS NULL RETURNING card_id;", "options": {}}}});
const n3 = node({"type": "n8n-nodes-base.postgres", "version": 2.6, "config": {"name": "Threads de hoje", "position": [672, 0], "credentials": {"postgres": {"id": "2QBGXkxxr41tWTQw", "name": "Postgres account"}}, "executeOnce": true, "alwaysOutputData": true, "parameters": {"operation": "executeQuery", "query": "CREATE TABLE IF NOT EXISTS discord_thread_dia (pessoa TEXT NOT NULL, data DATE NOT NULL, canal TEXT, thread_id TEXT, criado_em TIMESTAMPTZ DEFAULT now(), PRIMARY KEY (pessoa, data));\nSELECT pessoa, canal, thread_id FROM discord_thread_dia WHERE data = (now() AT TIME ZONE 'America/Recife')::date AND thread_id IS NOT NULL;", "options": {}}}});
const n4 = node({"type": "n8n-nodes-base.httpRequest", "version": 4.4, "config": {"name": "Clientes com grupo", "position": [896, 0], "credentials": {"httpHeaderAuth": {"id": "VYOze6gUMvjy3QXF", "name": "Notion Euforia"}}, "executeOnce": true, "parameters": {"method": "POST", "url": "https://api.notion.com/v1/databases/3ddc91b406be49e98e630c298d9162d8/query", "authentication": "genericCredentialType", "genericAuthType": "httpHeaderAuth", "sendHeaders": true, "headerParameters": {"parameters": [{"name": "Notion-Version", "value": "2022-06-28"}]}, "sendBody": true, "specifyBody": "json", "jsonBody": "={{ JSON.stringify({ filter: { and: [{ property: \"Situação\", select: { does_not_equal: \"Encerrado\" } }, { property: \"Grupo WhatsApp (ID)\", rich_text: { is_not_empty: true } }] }, page_size: 100 }) }}", "options": {"pagination": {"pagination": {"paginationMode": "updateAParameterInEachRequest", "parameters": {"parameters": [{"type": "body", "name": "start_cursor", "value": "={{ $response.body.next_cursor }}"}]}, "paginationCompleteWhen": "other", "completeExpression": "={{ !$response.body.has_more }}", "limitPagesFetched": true, "maxRequests": 10}}}}}});
