const n6 = node({"type": "n8n-nodes-base.code", "version": 2, "config": {"name": "Decidir cobrança", "position": [1344, 0], "parameters": {"jsCode": "// Cobrança da equipe V2 (Henrique 17/11, \"gerente funcional que entrega as demandas\"):\n// Henrique 17/11 (2ª versão): na hora (3 min) card \"RESPONDER GRUPO\" no painel do Rômulo (com rascunho) + aviso no 1x1; 10 min sem resposta: \"recebemos\" automático no grupo (Érica).\n// 1h: o Escritório responde no grupo com o rascunho (sai pelo fluxo de Aprovações, assinado Érica), exceto 🔴, assunto da diretoria ou rascunho que pede conferência: aí vai para a diretoria.\n// 2h: diretoria avisada. Valores/contrato/jurídico nunca vão para a equipe: diretoria direto.\nconst NL = String.fromCharCode(10);\nconst CANAL = { ismael: '1556650886678454403', romulo: '1556650881921978511', diretoria: '1567643418270634136', flau: '1554860447910330439' };\n// 25/11 (caso Jean): palavra de rompimento vira alerta imediato no #avisos-flau, a qualquer hora. Uma vez por espera.\nconst ALARME = /cancel|rescis|rescindir|distrato|falta de respeito|desrespeit|prejuizo|procon|advogad|reclame ?aqui|processo judicial|acao judicial/;\n// 25/11: aviso novo ao Rômulo (cliente cobrou de novo) só com o OK do Henrique. Até lá vai só para a diretoria.\nconst AVISAR_ROMULO_REPETIDA = false;\nconst USER = { ismael: '1410287139169763471', romulo: '1490768736876237082' };\nconst TRAVA = /r\\$|\\bpix\\b|boleto|pagament|\\bpagar\\b|paguei|cobranc|fatura|nota fiscal|reembols|estorn|parcela|mensalidade|\\bvalor(es)?\\b|desconto|\\bmulta\\b|contrato|cancelar|cancelament|rescis|distrato|advogad|procon|reclame ?aqui|processo|juridic/;\nconst sem = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();\nconst mascara = s => String(s || '').replace(/r\\$\\s*[\\d.,]+(\\s*(mil|k))?/gi, '[valor]').replace(/\\b\\d{1,3}(\\.\\d{3})+(,\\d{1,2})?\\b/g, '[valor]').replace(/https?:\\/\\/\\S+/g, '[link]').replace(/\\s+/g, ' ').slice(0, 220);\nconst fmt = m => m >= 60 ? Math.floor(m / 60) + 'h' + String(Math.round(m % 60)).padStart(2, '0') : Math.round(m) + ' min';\n// Mensagem que não pede resposta (ok, obrigado, bom dia, emoji): não cobra.\nconst TW = new Set('ok okay ta certo beleza blz combinado perfeito otimo show top obrigado obrigada obrigados obrigadas muito valeu grato grata amem bom boa dia tarde noite kk kkk kkkk rs sim entendi maravilha legal joia e pessoal gente romulo ismael daniel lorena erica victor equipe tudo certinho'.split(' '));\nconst trivial = l => { if (/\\[[a-z]+message\\]/i.test(l) && !/stickermessage/i.test(l)) return false; const w = sem(l).replace(/[^a-z\\s]/g, ' ').split(/\\s+/).filter(Boolean); return w.length <= 6 && w.every(x => TW.has(x)); };\nconst now = DateTime.now().setZone('America/Recife');\nconst FERIADOS = ['2026-11-20', '2026-12-25', '2027-01-01'];\nconst util = now.weekday <= 5 && !FERIADOS.includes(now.toISODate()) && now.hour >= 8 && now.hour < 18 && !(now.hour >= 12 && now.hour < 14);\nconst th = {};\nfor (const r of $('Threads de hoje').all()) if (r.json && r.json.canal && r.json.thread_id) th[r.json.canal] = r.json.thread_id;\nconst canalDe = q => th[CANAL[q]] || CANAL[q];\nconst post = (quem, texto) => ({ canal: quem === 'diretoria' ? CANAL.diretoria : quem === 'flau' ? CANAL.flau : canalDe(quem), corpo: JSON.stringify({ content: texto.slice(0, 1950), allowed_mentions: USER[quem] ? { users: [USER[quem]] } : { parse: [] } }) });\nconst txt = v => { if (!v) return ''; const a = v.title || v.rich_text; if (a) return a.map(t => t.plain_text).join('').trim(); if (v.select) return v.select.name; return ''; };\nconst cli = {};\nfor (const it of $('Clientes com grupo').all()) for (const p of (it.json.results || [])) {\n  const pr = p.properties || {};\n  const g = txt(pr['Grupo WhatsApp (ID)']).trim();\n  if (g) cli[g] = { id: p.id, nome: txt(pr['Cliente']), atencao: !!(pr['🔴 Atenção redobrada'] || {}).checkbox };\n}\n// 25/11 (Henrique, \"um robô só nos grupos\"): texto único e fixo, sem sorteio.\nconst ACOLHE = 'Oi! Recebemos sua mensagem e a equipe já está verificando por aqui. Em breve te retornamos.';\nconst linhas = [], envios = [], novos = [], autos = [], recibos = [], marcar = [];\nconst hm = d => DateTime.fromJSDate(new Date(d)).setZone('America/Recife').toFormat('dd/MM HH:mm');\nfor (const it of $('Clientes esperando').all()) {\n  const r = it.json;\n  if (!r.chave) continue;\n  const todas = String(r.todos || r.texto || '').split(NL).filter(Boolean);\n  if (todas.length && todas.every(trivial)) continue;\n  const c = cli[r.chat_id] || {};\n  // 25/11 (caso Jean), a qualquer hora: (a) palavra de rompimento -> #avisos-flau na hora; (b) cliente cobrou de novo sem resposta de verdade -> 🔴 diretoria + card marcado.\n  const alarme = !r.alarme_em && ALARME.test(sem(r.todos || r.texto));\n  const ultimaDt = r.ultima ? DateTime.fromJSDate(new Date(r.ultima)) : null;\n  const repetida = !r.repetida_em && Number(r.qtd) >= 2 && !!ultimaDt && ultimaDt.diff(DateTime.fromJSDate(new Date(r.desde)), 'minutes').minutes >= 30;\n  const ultLinha = mascara(todas[todas.length - 1] || r.texto);\n  if (alarme) envios.push(post('flau', '🚨 **' + (c.nome || r.grupo) + '** falou em rompimento no grupo (cancelamento, desrespeito, prejuízo ou jurídico). Esperando resposta de verdade desde ' + hm(r.desde) + '. Não respondi nada.' + NL + '> ' + r.autor + ': ' + mascara(r.todos || r.texto).slice(0, 400) + (r.card_url ? NL + 'Card: <' + r.card_url + '>' : '')));\n  if (repetida) {\n    envios.push(post('diretoria', '🔴 **' + (c.nome || r.grupo) + '** cobrou de novo e segue sem resposta de verdade desde ' + hm(r.desde) + ' (' + r.qtd + ' mensagens; \"vou verificar\", bom dia e resposta automática não contam).' + NL + '> 1ª: ' + mascara(r.texto) + NL + '> última (' + hm(r.ultima) + '): ' + ultLinha + (r.card_url ? NL + 'Card: <' + r.card_url + '>' : '')));\n    if (util && AVISAR_ROMULO_REPETIDA) envios.push(post('romulo', '🔴 <@' + USER.romulo + '> **' + (c.nome || r.grupo) + '** cobrou de novo no grupo e ainda não teve resposta de verdade. Responda agora pelo painel (Conversas › Sugerir resposta) com o que já foi feito e a data do que falta.' + (r.card_url ? NL + 'Card: <' + r.card_url + '>' : '')));\n    if (r.card_id) marcar.push({ card_id: r.card_id, titulo: '🔴 COBROU DE NOVO | ' + String(c.nome || r.grupo).toUpperCase() + ' | RESPONDER GRUPO | esperando desde ' + hm(r.desde) });\n  }\n  if (alarme || repetida) linhas.push({ chave: r.chave, chat_id: r.chat_id, grupo: r.grupo, desde: r.desde, n1: false, n2: false, n3: false, rec: false, rep: repetida, alarme: alarme });\n  if (!util) continue;\n  const abre = now.set({ hour: 8, minute: 0, second: 0, millisecond: 0 });\n  let ref = DateTime.fromJSDate(new Date(r.desde)).setZone('America/Recife');\n  if (ref < abre) ref = abre;\n  const a12 = now.set({ hour: 12, minute: 0, second: 0, millisecond: 0 }), a14 = now.set({ hour: 14, minute: 0, second: 0, millisecond: 0 });\n  let espera = now.diff(ref, 'minutes').minutes;\n  const ini = ref > a12 ? ref : a12, fim = now < a14 ? now : a14;\n  if (fim > ini) espera -= fim.diff(ini, 'minutes').minutes;\n  const nivel = espera >= 120 ? 3 : espera >= 60 ? 2 : espera >= 3 ? 1 : 0;\n  if (!nivel) continue;\n  const t = fmt(espera);\n  const extra = Number(r.qtd) > 1 ? ' (+' + (Number(r.qtd) - 1) + ' msg)' : '';\n  const trecho = '> ' + r.autor + ': ' + mascara(r.texto) + extra;\n  const base = { canal_romulo: canalDe('romulo'), chave: r.chave, chat_id: r.chat_id, grupo: r.grupo, cliente: c.nome || r.grupo, cliente_id: c.id || '', atencao: !!c.atencao, desde: r.desde, t, trecho, conversa: String(r.conversa || '') };\n  if (TRAVA.test(sem(r.todos || r.texto))) {\n    if (!r.n1_em) { envios.push(post('diretoria', '🚨 **' + r.grupo + '** espera resposta há ' + t + ' e o assunto é da diretoria (valores, contrato ou jurídico). Não passei para a equipe nem respondi. Fica com você.' + NL + trecho)); linhas.push({ chave: r.chave, chat_id: r.chat_id, grupo: r.grupo, desde: r.desde, n1: true, n2: true, n3: true, rec: false, rep: false, alarme: false }); }\n    continue;\n  }\n  if (!r.card_id) novos.push(base);\n  const n2 = nivel >= 2 && !r.n2_em, n3 = nivel >= 3 && !r.n3_em;\n  if (n2) autos.push(base);\n  // 10 min sem resposta: \"recebemos\" no grupo (uma vez por espera; não manda se o Escritório já vai responder agora).\n  // 25/11 (Henrique): sem \"recebemos\" quando a conversa está viva: cliente escreveu até 30 min depois da última resposta humana da equipe,\n  // ou é resposta curta (até 12 palavras, sem pergunta) a algo que a equipe disse nas últimas 12h. O card continua sendo criado.\n  const ultEq = r.ult_equipe ? DateTime.fromJSDate(new Date(r.ult_equipe)).setZone('America/Recife') : null;\n  const desdeDt = DateTime.fromJSDate(new Date(r.desde)).setZone('America/Recife');\n  const txtCli = String(r.todos || r.texto || '');\n  const nPal = sem(txtCli).replace(/[^a-z0-9\\s]/g, ' ').split(/\\s+/).filter(Boolean).length;\n  const conversaViva = !!ultEq && desdeDt.diff(ultEq, 'minutes').minutes <= 30;\n  const respostaCurta = !!ultEq && now.diff(ultEq, 'hours').hours <= 12 && nPal <= 12 && txtCli.indexOf('?') < 0;\n  // 25/11: se alguém da equipe já escreveu depois do cliente (mesmo um 'vou verificar'), não manda o 'recebemos' automático.\n  const equipeFalou = !!r.ult_qualquer && new Date(r.ult_qualquer) > new Date(r.desde);\n  const rec = !r.recebido_em && !r.n2_em && !n2 && espera >= 10 && !conversaViva && !respostaCurta && !equipeFalou;\n  if (rec) recibos.push({ chat_id: r.chat_id, texto: ACOLHE + NL + NL + '*Érica, time de suporte, Grupo Euforia*' });\n  if (n3 && r.n2_em) envios.push(post('diretoria', '🚨 **' + r.grupo + '** está há ' + t + ' sem resposta humana no grupo. O Rômulo recebeu o card na hora e o Escritório tentou responder com 1h.' + NL + trecho));\n  linhas.push({ chave: r.chave, chat_id: r.chat_id, grupo: r.grupo, desde: r.desde, n1: !r.n1_em, n2: n2, n3: n3, rec: rec, rep: false, alarme: false });\n}\nreturn [{ json: { linhas: JSON.stringify(linhas), envios, novos, autos, recibos, marcar } }];\n"}}});
const n7 = node({"type": "n8n-nodes-base.postgres", "version": 2.6, "config": {"name": "Gravar cobranças", "position": [1568, 0], "credentials": {"postgres": {"id": "2QBGXkxxr41tWTQw", "name": "Postgres account"}}, "alwaysOutputData": true, "parameters": {"operation": "executeQuery", "query": "INSERT INTO gerente_cobranca (chave, chat_id, grupo, desde, n1_em, n2_em, n3_em, recebido_em, repetida_em, alarme_em)\nSELECT x.chave, min(x.chat_id), min(x.grupo), min(x.desde), CASE WHEN bool_or(x.n1) THEN now() END, CASE WHEN bool_or(x.n2) THEN now() END, CASE WHEN bool_or(x.n3) THEN now() END, CASE WHEN bool_or(x.rec) THEN now() END, CASE WHEN bool_or(x.rep) THEN now() END, CASE WHEN bool_or(x.alarme) THEN now() END\nFROM json_to_recordset($1::json) AS x(chave text, chat_id text, grupo text, desde timestamptz, n1 boolean, n2 boolean, n3 boolean, rec boolean, rep boolean, alarme boolean)\nGROUP BY x.chave\nON CONFLICT (chave) DO UPDATE SET\n  n1_em = COALESCE(gerente_cobranca.n1_em, EXCLUDED.n1_em), n2_em = COALESCE(gerente_cobranca.n2_em, EXCLUDED.n2_em), n3_em = COALESCE(gerente_cobranca.n3_em, EXCLUDED.n3_em), recebido_em = COALESCE(gerente_cobranca.recebido_em, EXCLUDED.recebido_em), repetida_em = COALESCE(gerente_cobranca.repetida_em, EXCLUDED.repetida_em), alarme_em = COALESCE(gerente_cobranca.alarme_em, EXCLUDED.alarme_em)\nRETURNING chave;", "options": {"queryReplacement": "={{ [ $json.linhas ] }}"}}}});
