const n14 = node({"type": "n8n-nodes-base.code", "version": 2, "config": {"name": "Rascunho para o card", "position": [2016, 0], "parameters": {"jsCode": "// Monta o pedido ao Claude com o mesmo prompt da ferramenta \"Sugerir resposta\" do painel (tabela textos, chave sugerir_system, maior versão).\nconst NL = String.fromCharCode(10);\nconst linhasT = $('Ler textos').all().map(i => i.json).filter(r => r.chave === 'sugerir_system' && r.texto);\nlinhasT.sort((a, b) => (Number(b.versao) || 0) - (Number(a.versao) || 0));\nconst SYSTEM = (linhasT[0] || {}).texto || 'Escreva a resposta da equipe ao cliente. Responda só com JSON {\"resposta\": \"...\"}.';\nconst agora = DateTime.now().setZone('America/Recife');\nconst CAL = Array.from({ length: 8 }, (_, k) => agora.plus({ days: k }).setLocale('pt-BR').toFormat('cccc dd/MM')).join(', ');\nconst mascara = s => String(s || '').replace(/r\\$\\s*[\\d.,]+(\\s*(mil|k))?/gi, '[valor]');\nreturn $input.all().map(it => {\n  const x = it.json;\n  const user = 'Hoje é ' + agora.setLocale('pt-BR').toFormat('cccc dd/MM/yyyy HH:mm') + '. Próximos dias: ' + CAL + '.'\n    + NL + 'Cliente: ' + x.cliente + (x.atencao ? ' (🔴 atenção redobrada)' : '')\n    + NL + 'Quem vai enviar: ' + 'Rômulo (equipe)'\n    + NL + 'Orientação: o cliente está esperando resposta há ' + x.t + '. Responda à última mensagem dele; se não dá para resolver agora, diga o próximo passo concreto sem prometer data.'\n    + NL + NL + 'Agenda das calls e tutorias da equipe: (indisponível agora: não proponha horário, diga que o time confere a agenda e confirma por aqui)'\n    + NL + NL + 'Conversa do grupo (mais antiga em cima):' + NL + mascara(x.conversa || '(sem mensagens)');\n  return { json: { ...x, corpo: JSON.stringify({ model: 'claude-sonnet-4-5', max_tokens: 900, temperature: 0.3, system: SYSTEM, messages: [{ role: 'user', content: user }] }) } };\n});\n"}}});
