const n24 = node({"type": "n8n-nodes-base.code", "version": 2, "config": {"name": "Ler rascunho do Escritório", "position": [2464, 320], "parameters": {"jsCode": "// Frases proibidas a cliente (Henrique, 18/11): concordar com reclamação, admitir falha/atraso, \"agência\", IA, citar a diretoria.\nconst PROIB = [\n  ['concordar com a reclamação (\"você tem razão\")', /\\b(voce|vc|ce)\\s+(tem|ta|esta)\\s+(toda\\s+|total\\s+|muita\\s+|completa\\s+)?(a\\s+)?razao\\b|\\btem\\s+toda\\s+(a\\s+)?razao\\b|\\bcom\\s+(toda|muita)\\s+razao\\b|\\bfaz\\s+(todo|total|muito)\\s+(o\\s+)?sentido\\b|\\bvoce\\s+esta\\s+cert[oa]\\b|\\b(entendo|compreendo)\\s+(perfeitamente\\s+|totalmente\\s+)?(a\\s+|sua\\s+|a\\s+sua\\s+)?(frustracao|insatisfacao|chateacao)/],\n  ['\"agência\" (somos empresa de mídia)', /\\bagencias?\\b/],\n  ['admitir falha, erro ou atraso', /\\b(erro|erros|erramos|errei|falha|falhas|falhamos|atraso|atrasos|atrasou|atrasamos|atrasad[oa]s?|demoramos|demorou|demora|gargalos?|oscilacao|oscilacoes|instabilidade|desculpa|desculpas|desculpe|perdao|lamentamos|deixamos\\s+a\\s+desejar)\\b|\\bsentimos\\s+muito\\b|\\bfase\\s+de\\s+ajustes?\\b|\\bproblemas?\\s+intern|\\bqueda\\s+(na|no|da|do)\\s+(recorrencia|ritmo|frequencia|constancia)/],\n  ['falar de IA', /\\b(inteligencia\\s+artificial|chatgpt|gpt|robo|robos)\\b/],\n  ['citar a diretoria', /\\b(henrique|flau)\\b/]\n];\nconst semAcento = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase();\nconst proibidos = t => { const n = semAcento(t); const r = PROIB.filter(p => p[1].test(n)).map(p => p[0]); if (/(^|[^A-Za-z])IAs?([^A-Za-z]|$)/.test(String(t || '')) && !r.includes('falar de IA')) r.push('falar de IA'); return r; };\nconst limparProibidas = t => { const tir = new Set();\n  const pars = String(t || '').split(/\\n\\s*\\n/).map(p => (p.match(/[^.!?\\n]+[.!?]*\\s*|\\n/g) || []).filter(f => { const q = proibidos(f); q.forEach(x => tir.add(x)); return !q.length; }).join('').trim()).filter(Boolean);\n  return { texto: pars.join('\\n\\n'), tirou: Array.from(tir) }; };\nreturn $input.all().map((it, i) => {\n  const x = $('Rascunho do Escritório').itemMatching(i).json;\n  const r = it.json || {};\n  let s = {};\n  try { const t = ((r.content || [])[0] || {}).text || ''; s = JSON.parse((t.match(/\\{[\\s\\S]*\\}/) || ['{}'])[0]); } catch (e) { s = {}; }\n  const lp = limparProibidas(String(s.resposta || '').replace(/R[$]\\s?[0-9.,]+/g, '').trim().slice(0, 1500));\n  const texto = lp.texto;\n  return { json: { ...x, corpo: undefined, sugestao: texto, diretoria: String(s.diretoria || '').slice(0, 300), conferir: (lp.tirou.length ? 'Tirei do rascunho frase proibida (' + lp.tirou.join(', ') + '). Releia antes de enviar. ' : '') + String(s.conferir || '').slice(0, 300), proibido: lp.tirou.join(', ') } };\n});\n"}}});
const n25 = node({"type": "n8n-nodes-base.code", "version": 2, "config": {"name": "Decidir resposta do Escritório", "position": [2688, 320], "parameters": {"jsCode": "// 1h sem resposta humana (Henrique 17/11, opção \"Escritório (eu respondo)\"): o Escritório responde no grupo com o rascunho.\n// Não sai sozinho: cliente 🔴, rascunho que pede decisão da diretoria ou conferência da equipe, ou com [marcador] para preencher.\nconst NL = String.fromCharCode(10);\nreturn $input.all().map(it => {\n  const x = it.json;\n  let motivo = '';\n  if (!x.sugestao) motivo = 'não consegui gerar o rascunho';\n  else if (x.proibido) motivo = 'o rascunho tinha frase proibida (' + x.proibido + ')';\n  else if (x.atencao) motivo = 'cliente 🔴 (atenção redobrada)';\n  else if (x.diretoria) motivo = 'pede decisão da diretoria: ' + x.diretoria;\n  else if (x.conferir) motivo = 'precisa conferir com a equipe: ' + x.conferir;\n  else if (/\\[[^\\]]{3,}\\]/.test(x.sugestao)) motivo = 'o rascunho tem campo para preencher';\n  const ok = !motivo;\n  const t = ok\n    ? '🤖 **' + x.grupo + '** · ' + x.t + ' sem resposta humana. O Rômulo recebeu o card na hora; o **Escritório responde agora** no grupo (sai em até 2 min, cancele no painel › Aprovar se precisar).' + NL + x.trecho + NL + '>>> ' + x.sugestao\n    : '🚨 **' + x.grupo + '** · ' + x.t + ' sem resposta humana e eu não respondi sozinho: ' + motivo + '. Fica com você.' + NL + x.trecho + (x.sugestao ? NL + '✍️ Rascunho:' + NL + '>>> ' + x.sugestao : '');\n  return { json: { ...x, ok, motivo, corpo: JSON.stringify({ content: t.slice(0, 1990), allowed_mentions: { parse: [] } }) } };\n});\n"}}});
